#include <FFPPcc.hpp>
#include <FArray.hpp>
#include <Need.hpp>
#include <W1jet.hpp>
#include <cmath>
#include <complex>
#include <mxpart_mod.hpp>
#include <sprods_com_mod.hpp>

using namespace mxpart_mod;
using namespace sprods_com_mod;

// Z. Bern, L. Dixon, D.A. Kosower, e-Print:hep-ph/9708239
// Eq10.4
std::complex<double> FFPPcc1(int j1, int j2, int j3, int j4, int j5, int j6, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
  auto zab = [&za, &zb](int i1, int i2, int i3) {
    return za(i1, i2) * zb(i2, i3);
  };

  std::complex<double> res =
      -2.0 * za(j5, j2) * zab(j5, j4, j3)
      / (za(j3, j4) * za(j4, j1) * za(j5, j6));

  return res;
}

// Z. Bern, L. Dixon, D.A. Kosower, e-Print:hep-ph/9708239
// Eq10.4
std::complex<double> FFPPcc2(int j1, int j2, int j3, int j4, int j5, int j6, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
  auto zab2 = [&za, &zb](int i1, int i2, int i3, int i4) {
    return za(i1, i2) * zb(i2, i4) + za(i1, i3) * zb(i3, i4);
  };

  std::complex<double> res =
      2.0 * za(j2, j5) * za(j1, j5) * zab2(j2, j3, j4, j1)
      / (za(j2, j3) * za(j3, j4) * za(j4, j1) * za(j5, j6));

  return res;
}

// Z. Bern, L. Dixon, D.A. Kosower, e-Print:hep-ph/9708239
// Eq10.4
std::complex<double> FFPPcc(int j1, int j2, int j3, int j4, int j5, int j6, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
  double s123 = t(j1, j2, j3);
  double s234 = t(j2, j3, j4);

  std::complex<double> termA =
      za(j2, j5) * (za(j1, j2) * za(j4, j5) - za(j2, j4) * za(j1, j5))
      / (za(j2, j3) * za(j3, j4) * std::pow(za(j4, j1), 2) * za(j5, j6))
      * Lsm1_2me(s123, s234, s(j2, j3), s(j5, j6));

  std::complex<double> termB =
      za(j2, j5) * (za(j2, j3) * za(j1, j5) - za(j1, j2) * za(j3, j5))
      / (za(j2, j3) * za(j3, j4) * za(j4, j1) * za(j1, j3) * za(j5, j6))
      * Lsm1(-s(j1, j2), -s123, -s(j2, j3), -s123);

  std::complex<double> termC =
      -za(j2, j5) * (za(j2, j3) * za(j4, j5) + za(j2, j4) * za(j3, j5))
      / (za(j2, j3) * std::pow(za(j3, j4), 2) * za(j4, j1) * za(j5, j6))
      * Lsm1_2me(t(j1, j2, j4), s123, s(j1, j2), s(j5, j6));

  std::complex<double> termD =
      -std::pow(za(j5, j2), 2) / (za(j2, j3) * za(j3, j4) * za(j4, j1) * za(j5, j6))
      * (Lsm1(-s(j1, j4), -t(j1, j2, j4), -s(j1, j2), -t(j1, j2, j4))
         + Lsm1_2me(t(j1, j3, j4), t(j1, j2, j4), s(j1, j4), s(j5, j6)));

  std::complex<double> termE =
      FFPPcc1(j1, j2, j3, j4, j5, j6, za, zb) * L0(-s234, -s(j2, j3)) / s(j2, j3);

  std::complex<double> termF =
      FFPPcc2(j1, j2, j3, j4, j5, j6, za, zb) * L0(-s234, -s(j5, j6)) / s(j5, j6);

  std::complex<double> res = termA + termB + termC + termD + termE + termF; // @coverage-probe

  return res;
}

extern "C" {
  std::complex<double> FFPPcc_wrapper(int j1, int j2, int j3, int j4, int j5, int j6, std::complex<double>* fza, std::complex<double>* fzb) {
    FArray2D<std::complex<double>> za(fza, mxpart, mxpart);
    FArray2D<std::complex<double>> zb(fzb, mxpart, mxpart);

    return FFPPcc(j1, j2, j3, j4, j5, j6, za, zb);
  }
}
