#include <M1bit1.hpp>

#include <cmath>
#include <complex>
#include <FArray.hpp>
#include <mxpart_mod.hpp>
#include <sprods_com_mod.hpp>
#include <W1jet.hpp>

using namespace mxpart_mod;
using namespace sprods_com_mod;

// Z. Bern, L. Dixon, D.A. Kosower, e-Print:hep-ph/9708239
// Eq 7.1
std::complex<double> M1bit1(int j1, int j2, int j3, int j4, int j5, int j6, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
  // Statement functions
  auto zab2 = [&za, &zb](int i1, int i2, int i3, int i4) {
    return za(i1, i2) * zb(i2, i4) + za(i1, i3) * zb(i3, i4);
  };
  auto zba2 = [&za, &zb](int i1, int i2, int i3, int i4) {
    return zb(i1, i2) * za(i2, i4) + zb(i1, i3) * za(i3, i4);
  };
  auto zab = [&za, &zb](int i1, int i2, int i3) {
    return za(i1, i2) * zb(i2, i3);
  };
  // End statement functions

  double delta12 = s(j1, j2) - s(j3, j4) - s(j5, j6);
  double delta56 = s(j5, j6) - s(j1, j2) - s(j3, j4);
  double Delta3 = std::pow(s(j1, j2), 2) + std::pow(s(j3, j4), 2) + std::pow(s(j5, j6), 2)
      - 2 * s(j1, j2) * s(j3, j4) - 2 * s(j3, j4) * s(j5, j6) - 2 * s(j5, j6) * s(j1, j2);

  std::complex<double> res =
      2.0 / (zab2(j1, j3, j4, j2) * zab2(j3, j1, j2, j4) * Delta3)
      * (zb(j1, j3) / za(j5, j6)
           * (za(j2, j1) * zba2(j1, j3, j4, j5)
                - (zab2(j2, j3, j4, j1) * za(j1, j5) + zab2(j2, j3, j4, j2) * za(j2, j5)))
           * (za(j1, j5) * t(j1, j2, j4) + zab(j1, j2, j6) * za(j6, j5))
         - zb(j1, j6) * za(j2, j4) / (za(j3, j4) * zb(j5, j6))
           * ((s(j1, j4) - s(j2, j3))
                * (zab(j1, j2, j6) * delta12 - zab(j1, j5, j6) * delta56)
              + zab2(j1, j3, j4, j2) * (zab(j2, j1, j6) * delta12 - zab(j2, j5, j6) * delta56))
         + 2.0 * zab(j2, j1, j3) * zab2(j5, j1, j2, j6) * (s(j1, j4) - s(j2, j3))); // @coverage-probe

  return res;
}

extern "C" {
  std::complex<double> M1bit1_wrapper(int j1, int j2, int j3, int j4, int j5, int j6, std::complex<double>* fza, std::complex<double>* fzb) {
    FArray2D<std::complex<double>> za(fza, mxpart, mxpart);
    FArray2D<std::complex<double>> zb(fzb, mxpart, mxpart);

    return M1bit1(j1, j2, j3, j4, j5, j6, za, zb);
  }
}
